const D = { hue: 45, energy: .62, speed: 1, density: .6, scale: 1, x: .5, y: .66, n: 12, rows: 2, march: .6, style: 'poster', pal: 'classic', act: 'parade', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const ease = t => t < .5 ? 2*t*t : 1 - Math.pow(-2*t+2, 2)/2;
const N = Math.max(4, Math.min(24, Math.round(P.n)));
const ho = P.hue - 45;

// palettes: [uniform, trim, plume, brass, skin]  each [h,s,b]
const PAL = {
  classic: { uni:[42,10,92], trim:[220,60,34], plume:[0,78,86], brass:[44,82,90], skin:[28,34,74], ink:[220,40,14] },
  gold:    { uni:[36,14,16], trim:[44,70,58], plume:[44,88,94], brass:[46,88,96], skin:[30,30,66], ink:[40,30,8]  },
  crimson: { uni:[352,64,54], trim:[42,10,94], plume:[46,86,92], brass:[44,84,92], skin:[26,32,72], ink:[352,50,14]},
  teal:    { uni:[184,44,60], trim:[40,8,94],  plume:[8,74,88],  brass:[44,80,90], skin:[28,32,72], ink:[196,50,12]},
  mono:    { uni:[220,6,84],  trim:[220,8,24], plume:[220,10,96],brass:[220,6,64], skin:[220,6,60], ink:[220,10,10]} };
const pc = PAL[P.pal] || PAL.classic;
const tint = c => [hw(c[0] + ho * .5), c[1], c[2]];
const sty = P.style;
const wire = sty === 'blueprint';
const noir = sty === 'noir';
const riso = sty === 'riso';
const brass = sty === 'brass';

// ---- cached poster wash (ground band + halftone speckle), translucent so a bed shows ----
const wk = width + 'x' + height + sty + P.pal + P.seed + Math.round(P.hue);
if (!S.wash || S.wk !== wk) {
  if (!S.wash) S.wash = createGraphics(width, height);
  else S.wash.resizeCanvas(width, height);
  const g = S.wash; g.clear();
  g.colorMode(g.HSB, 360, 100, 100, 100); g.noStroke();
  const gy = height * (P.y + .07);
  if (!wire) {
    // warm ground stripe
    const gc = tint(pc.ink);
    for (let yy = gy; yy < height; yy++) {
      const t = (yy - gy) / Math.max(1, height - gy);
      g.fill(gc[0], gc[1] * .8, gc[2] + t * 10, 26 + t * 22);
      g.rect(0, yy, width, 1);
    }
    // halftone dot texture over ground (poster tell)
    const dot = riso ? 2.4 : 1.8, step = u * .022;
    for (let yy = gy; yy < height; yy += step)
      for (let xx = 0; xx < width; xx += step) {
        const t = (yy - gy) / Math.max(1, height - gy);
        const r = dot * (1.1 - t * .5) * (.6 + fr(xx * .3 + yy) * .8);
        g.fill(gc[0], 20, gc[2] + 30, 22 * (1 - t * .5));
        g.ellipse(xx, yy, r, r);
        if (riso) { const rc = tint(pc.trim); g.fill(rc[0], rc[1], rc[2], 12); g.ellipse(xx + step*.4, yy, r*.8, r*.8); }
      }
  } else {
    // blueprint grid
    const bc = [200, 70, 60];
    g.stroke(bc[0], bc[1], bc[2], 16); g.strokeWeight(1);
    for (let xx = 0; xx <= width; xx += u * .06) g.line(xx, 0, xx, height);
    for (let yy = 0; yy <= height; yy += u * .06) g.line(0, yy, width, yy);
    g.noStroke();
  }
  S.wk = wk;
}
image(S.wash, 0, 0);

// ---- drifting bunting / banner ribbon high across the field (K.t continuous motion floor) ----
push();
const by = height * (P.y - .42);
const drift = K.t * (18 + 30 * P.march) * P.speed;
if (!wire) {
  strokeWeight(u * .006); noStroke();
  const seg = Math.max(6, Math.floor(width / (u * .16)));
  for (let i = 0; i <= seg; i++) {
    const fx = ((i * (width / seg) - (drift % width)) % width + width) % width;
    const swg = Math.sin(K.t * .8 + i * .7) * u * .012;
    const fy = by + swg + Math.sin(i * 1.3) * u * .01;
    const fc = i % 2 ? tint(pc.trim) : tint(pc.plume);
    fill(fc[0], fc[1], noir ? 30 : fc[2], noir ? 40 : 70);
    triangle(fx, fy, fx + u * .05, fy, fx + u * .025, fy + u * .06);
  }
} else {
  stroke(200, 60, 80, 50); strokeWeight(1);
  const yy = by; line(0, yy, width, yy);
  for (let xx = 0; xx < width; xx += u * .05) line(xx, yy, xx + u * .012, yy + u * .05);
  noStroke();
}
pop();

// ---- formation ----
const rows = Math.max(1, Math.min(4, Math.round(P.rows)));
const perRow = Math.ceil(N / rows);
const inten = .55 + .6 * K.intensity;
const cx = P.x * width, baseY = P.y * height;
const fieldW = u * (1.7 + perRow * .12) * P.scale;
const colGap = fieldW / perRow;
const step = u * .12 * P.scale;
const mSpeed = (14 + 26 * P.march) * P.speed;
const roll = K.t * mSpeed;

// act tables: [stepH, sway, cadence]
const sec = ((Math.floor(K.section) % 8) + 8) % 8;
const ACT = {
  parade:  [[1,1,1],[1.1,1,1],[1,1.2,1],[1.2,1,1],[.9,1.1,1.15],[1.1,1,1],[1,1.1,1],[1.15,1,1.1]],
  fanfare: [[1.3,1.2,1],[1.5,1,1],[1.2,1.4,1],[1.5,1,1.2],[1.1,1.3,1],[1.5,1,1],[1.3,1.2,1],[1.5,1,1.2]],
  slowmarch:[[.7,.8,.6],[.8,.7,.6],[.7,.9,.55],[.8,.7,.6],[.6,.8,.6],[.8,.7,.55],[.7,.9,.6],[.8,.7,.6]] };
const aw = (ACT[P.act] || ACT.parade)[sec];
const stepH = P.energy * aw[0], swayA = aw[1], cadence = aw[2];

// draw back rows first (perspective: back = smaller, higher)
const members = [];
for (let i = 0; i < N; i++) {
  const row = i % rows, col = Math.floor(i / rows);
  const depth = rows > 1 ? row / (rows - 1) : 0;      // 0 front .. 1 back
  members.push({ i, row, col, depth });
}
members.sort((a, b) => b.depth - a.depth);

for (const m of members) {
  const { i, col, depth } = m;
  const dScale = 1 - depth * .3;
  const rx = (col + .5) * colGap - fieldW / 2 + cx - (roll % colGap);
  // wrap into field
  let mx = rx;
  const leftEdge = cx - fieldW / 2 - colGap;
  if (mx < leftEdge) mx += Math.ceil((leftEdge - mx) / fieldW) * fieldW;
  const my = baseY - depth * u * .16 * P.scale + Math.sin(K.t * 1.2 + i) * u * .004;
  if (mx < -colGap || mx > width + colGap) continue;

  const sz = step * dScale;                // body height unit
  const beatPh = (K.beat * cadence * P.speed + col * .5 + m.row * .25);
  const lift = ((beatPh % 1) + 1) % 1;
  const legA = Math.sin(beatPh * TAU) * .8 * stepH;   // alternate thigh swing
  const bob = Math.abs(Math.sin(beatPh * Math.PI)) * sz * .09 * (.5 + stepH);
  const sway = Math.sin(K.t * 1.4 + i * .6) * sz * .04 * swayA;
  const alpha = 78 - depth * 22;

  push();
  translate(mx + sway, my - bob);

  const uni = tint(pc.uni), trim = tint(pc.trim), plume = tint(pc.plume), br = tint(pc.brass), sk = tint(pc.skin);
  const shade = brass || noir;
  const setFill = (c, aa, dark) => {
    if (wire) { noFill(); stroke(200, 60, 84, alpha); strokeWeight(1.1 * dScale); return; }
    noStroke();
    if (noir) { fill(c[0], c[1] * .5, dark ? 8 : 16, alpha + 12); return; }
    fill(c[0], c[1], dark ? c[2] * .62 : c[2], aa);
  };

  // ground shadow
  if (!wire) { noStroke(); fill(pc.ink[0], 30, 6, 22); ellipse(0, sz * .96 + bob, sz * .7 * dScale, sz * .16 * dScale); }

  // legs (high-step) — two, alternating
  const lw = sz * .12;
  for (const s of [-1, 1]) {
    const swing = legA * s;
    const knee = Math.max(0, swing) ;          // front leg lifts
    push();
    translate(s * sz * .13, sz * .34);
    rotate(swing * .5);
    setFill(trim, alpha, true);
    if (wire) { line(0, 0, 0, sz * .5); line(0, sz * .5, -swing * sz * .3, sz * .62); }
    else { rectMode(CENTER); rect(0, sz * .26, lw, sz * .52, lw * .4);
           push(); translate(-swing * sz * .18, sz * .52); rotate(-swing * .3);
           setFill(pc.ink, alpha); rect(0, sz * .04, lw * 1.5, sz * .1, lw * .3); pop(); }
    pop();
  }

  // torso jacket
  setFill(uni, alpha);
  if (wire) { rect(-sz*.2, -sz*.18, sz*.4, sz*.5); }
  else {
    beginShape();
    vertex(-sz * .22, -sz * .18); vertex(sz * .22, -sz * .18);
    vertex(sz * .2, sz * .34); vertex(-sz * .2, sz * .34); endShape(CLOSE);
    // chevron sash / trim
    setFill(trim, alpha, true);
    quad(-sz*.22,-sz*.16, -sz*.02,-sz*.02, -sz*.02, sz*.06, -sz*.22,-sz*.06);
    quad(sz*.22,-sz*.16, sz*.02,-sz*.02, sz*.02, sz*.06, sz*.22,-sz*.06);
    // buttons
    if (!noir) { setFill(br, alpha); for (let b=0;b<3;b++) ellipse(0, -sz*.08 + b*sz*.12, sz*.05, sz*.05); }
  }

  // arms holding instrument
  const carry = fr(i * 3 + 2);
  const isDrum = carry > .62;
  setFill(uni, alpha, true);
  if (!wire) { rectMode(CENTER); rect(-sz*.27, -sz*.02, lw*.9, sz*.3, lw*.4); rect(sz*.27, -sz*.02, lw*.9, sz*.3, lw*.4); }

  // head + shako
  const hy = -sz * .38;
  setFill(sk, alpha);
  if (wire) ellipse(0, hy, sz*.24, sz*.28); else ellipse(0, hy, sz * .24, sz * .27);
  // shako (tall hat)
  setFill(noir || brass ? pc.ink : trim, alpha, true);
  if (wire) rect(-sz*.12, hy - sz*.5, sz*.24, sz*.4);
  else { rectMode(CENTER); rect(0, hy - sz * .28, sz * .26, sz * .36, sz*.03);
         setFill(br, alpha); rect(0, hy - sz*.12, sz*.28, sz*.05); }
  // plume (sways)
  const pl = Math.sin(K.t * 2 + i) * sz * .05;
  if (wire) { stroke(0,74,86,alpha); strokeWeight(1.2*dScale); line(0, hy-sz*.46, pl, hy-sz*.72); noStroke(); }
  else { setFill(plume, alpha); ellipse(pl*.5, hy - sz*.58, sz*.1, sz*.28); }

  // instrument + beat flash
  const beatFlash = K.pulse * .8 + A.bass * .7 + K.swell * .1;
  const glow = Math.min(1, beatFlash * (.6 + P.energy));
  if (isDrum) {
    // snare/bass drum in front, mallet strikes on beat
    const dr = sz * .3;
    setFill(pc.uni, alpha); if (wire){noFill();stroke(200,60,84,alpha);} ellipse(0, sz*.16, dr*1.05, dr*1.05);
    if (!wire) { noStroke(); fill(46, 10, 92, alpha * (.6 + glow*.4)); ellipse(0, sz*.16, dr*.8, dr*.8);
      stroke(br[0], br[1], br[2], alpha); strokeWeight(sz*.02);
      for (let z=0;z<3;z++){ const aa=z/3*TAU; line(0,sz*.16,Math.cos(aa)*dr*.5, sz*.16+Math.sin(aa)*dr*.5);} noStroke(); }
    // mallet
    const strike = Math.max(0, 1 - lift*2);
    if (!wire){ stroke(sk[0],sk[1],sk[2],alpha); strokeWeight(sz*.03);
      const mx2 = sz*.34, myTop = sz*.16 - sz*.24*strike; line(sz*.2,-sz*.02,mx2,myTop); noStroke();
      fill(br[0],br[1],br[2],alpha); ellipse(mx2,myTop,sz*.07,sz*.07); }
    if (glow > .12){ push(); blendMode(ADD); noStroke(); fill(44,60,96, 30*glow); ellipse(0,sz*.16,dr*1.5,dr*1.5); blendMode(BLEND); pop(); }
  } else {
    // horn — bell flares up-right, flashes when played
    push(); translate(sz*.22, -sz*.06); rotate(-.5 + Math.sin(K.t*.9+i)*.05);
    if (wire) { noFill(); stroke(200,60,84,alpha); strokeWeight(1.2*dScale);
      line(0,0,sz*.34,-sz*.12); ellipse(sz*.4,-sz*.16, sz*.24, sz*.2); }
    else {
      stroke(br[0], br[1], Math.min(100, br[2] + glow*10), alpha); strokeWeight(sz*.05);
      line(0, 0, sz*.32, -sz*.12); noStroke();
      // bell
      fill(br[0], br[1]*.8, Math.min(100, br[2] + glow*14), alpha);
      beginShape(); vertex(sz*.3,-sz*.02); vertex(sz*.34,-sz*.24);
      vertex(sz*.5,-sz*.3); vertex(sz*.5,-sz*.02); endShape(CLOSE);
      // inner
      fill(46, 20, Math.min(100, 80 + glow*20), alpha*.8); ellipse(sz*.44,-sz*.16, sz*.12, sz*.16);
    }
    // flash burst on beat
    if (glow > .12) { push(); blendMode(ADD); noStroke();
      fill(48, 40, 98, 34 * glow); ellipse(sz*.46, -sz*.18, sz*.55*(1+glow), sz*.5*(1+glow));
      blendMode(BLEND); pop(); }
    pop();
  }

  pop();
}
blendMode(BLEND);
